add_filter( 'woocommerce_product_categories', 'perfectpixel_exclude_from_categories_shortcode' );
add_filter( 'woocommerce_product_subcategories_args', 'perfectpixel_exclude_from_shop_categories' );

function perfectpixel_exclude_from_categories_shortcode( $terms ) {
	$ids = wp_parse_id_list( '{{categories_shortcode_excluded_ids}}' );
	if ( ! $ids || ! is_array( $terms ) ) {
		return $terms;
	}
	return array_values(
		array_filter(
			$terms,
			function ( $term ) use ( $ids ) {
				return ! in_array( (int) $term->term_id, $ids, true );
			}
		)
	);
}

function perfectpixel_exclude_from_shop_categories( $args ) {
	$ids = wp_parse_id_list( '{{categories_shortcode_excluded_ids}}' );
	if ( $ids ) {
		$args['exclude'] = array_merge( isset( $args['exclude'] ) ? wp_parse_id_list( $args['exclude'] ) : array(), $ids );
	}
	return $args;
}
